<script setup lang="ts">
import{computed,onMounted,ref,watch}from'vue';import type{ColDef}from'ag-grid-community';import AppDataGrid from'@/components/AppDataGrid.vue';import{getSSLTask,listCertificates,listSSLTasks,type SSLCertificate,type SSLTask}from'@/api/ssl-cert'
const rows=ref<SSLTask[]>([]),certs=ref<SSLCertificate[]>([]),certID=ref(0),taskType=ref(''),status=ref(''),triggerType=ref(''),page=ref(1),pageSize=ref(20),total=ref(0),loading=ref(false),dialog=ref(false),detail=ref<SSLTask|null>(null)
async function load(){loading.value=true;try{const{data}=await listSSLTasks({certificate_id:certID.value,task_type:taskType.value,status:status.value,trigger_type:triggerType.value,page:page.value,limit:pageSize.value});rows.value=data.data.list;total.value=data.data.total}finally{loading.value=false}}async function open(row:SSLTask){const{data}=await getSSLTask(row.id);detail.value=data.data;dialog.value=true}function actions(p:{data:SSLTask}){const w=document.createElement('div');w.className='ssl-grid-actions';const b=document.createElement('button');b.type='button';b.className='grid-action compact edit';b.textContent='查看';b.addEventListener('click',event=>{event.stopPropagation();void open(p.data)});w.append(b);return w}const time=(v:string|null)=>v?String(v).replace('T',' ').slice(0,19):'-';const columns=computed<ColDef[]>(()=>[{headerName:'序号',width:64,valueGetter:p=>(page.value-1)*pageSize.value+(p.node?.rowIndex||0)+1},{field:'certificate_name',headerName:'证书',minWidth:150},{field:'task_type',headerName:'任务类型',width:100,valueFormatter:p=>({issue:'签发',renew:'续期',deploy:'部署'}[p.value as string]||p.value)},{field:'status',headerName:'状态',width:90,valueFormatter:p=>({pending:'等待中',running:'执行中',success:'成功',failed:'失败'}[p.value as string]||p.value)},{field:'trigger_type',headerName:'触发方式',width:90,valueFormatter:p=>p.value==='auto'?'自动':'手动'},{field:'started_at',headerName:'开始时间',minWidth:145,valueFormatter:p=>time(p.value)},{field:'finished_at',headerName:'完成时间',minWidth:145,valueFormatter:p=>time(p.value)},{field:'error_message',headerName:'错误信息',minWidth:160,valueFormatter:p=>p.value||'-'},{headerName:'操作',pinned:'right',width:150,minWidth:150,maxWidth:150,cellClass:'ssl-operation-cell',cellRenderer:actions}]);watch([certID,taskType,status,triggerType],()=>{page.value=1;void load()});onMounted(async()=>{await load();const{data}=await listCertificates({keyword:'',status:'',source_type:'',page:1,limit:1000});certs.value=data.data.list})
</script>
<template><section class="ssl-page"><header><h2>任务记录</h2><p>查看证书签发、续期和部署任务的执行记录。</p></header><div class="filters"><el-select v-model="certID" placeholder="选择证书" clearable><el-option v-for="item in certs" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-select v-model="taskType" placeholder="选择任务类型" clearable><el-option label="签发" value="issue"/><el-option label="续期" value="renew"/><el-option label="部署" value="deploy"/></el-select><el-select v-model="status" placeholder="选择状态" clearable><el-option label="等待中" value="pending"/><el-option label="执行中" value="running"/><el-option label="成功" value="success"/><el-option label="失败" value="failed"/></el-select><el-select v-model="triggerType" placeholder="选择触发方式" clearable><el-option label="手动" value="manual"/><el-option label="自动" value="auto"/></el-select></div><AppDataGrid v-loading="loading" class="grid" :row-data="rows" :column-defs="columns" pagination server-pagination :total="total" :current-page="page" :page-size="pageSize" @page-change="v=>{page=v;void load()}" @page-size-change="v=>{pageSize=v;page=1;void load()}"/><el-dialog v-model="dialog" title="任务详情" width="720px"><div v-if="detail" class="detail"><div><span>证书</span><strong>{{detail.certificate_name}}</strong></div><div><span>任务类型</span><strong>{{detail.task_type}}</strong></div><div><span>状态</span><strong>{{detail.status}}</strong></div><div><span>触发方式</span><strong>{{detail.trigger_type}}</strong></div><section><h3>执行结果</h3><pre>{{detail.result||'暂无结果'}}</pre></section><section v-if="detail.error_message"><h3>错误信息</h3><pre class="error">{{detail.error_message}}</pre></section></div></el-dialog></section></template>
<style scoped>.ssl-page{height:100%;display:flex;flex-direction:column;gap:8px;min-width:0;padding:0 4px;font-size:11px}header h2{margin:0;font-size:20px}header p{margin:3px 0 0;color:var(--text-soft)}.filters{display:flex;gap:6px}.filters .el-select{width:145px}.grid{flex:1;min-height:0}:deep(.task-actions){height:100%;display:flex;align-items:center}:deep(.view-button){height:26px;border:1px solid var(--primary);border-radius:8px;padding:3px 9px;background:#fff;color:var(--primary);cursor:pointer}.detail{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--line);border-radius:9px;overflow:hidden}.detail>div{display:grid;grid-template-columns:80px 1fr;align-items:center;min-height:38px;border-bottom:1px solid var(--line)}.detail>div:nth-child(odd){border-right:1px solid var(--line)}.detail span{align-self:stretch;display:flex;align-items:center;padding:0 10px;background:#f7f8fb;color:var(--text-soft)}.detail strong{padding:0 10px}.detail section{grid-column:1/-1;padding:10px;border-top:1px solid var(--line)}.detail h3{margin:0 0 7px;font-size:12px}.detail pre{margin:0;padding:9px;border-radius:7px;background:#17191e;color:#e7eaf0;white-space:pre-wrap}.detail pre.error{background:#fff5f5;color:var(--danger)}</style>
